<script lang="ts">
  import type { Block } from '../model';
  let {selected,patch}:{selected:Block;patch:(v:Record<string,unknown>)=>void}=$props();
  function rows(field:string):Record<string,unknown>[] {return ((selected as unknown as Record<string,unknown>)[field] || []) as Record<string,unknown>[];}
  function update(field:string,index:number,value:Record<string,unknown>){patch({[field]:rows(field).map((r,i)=>i===index?{...r,...value}:r)});}
  function add(field:string,value:Record<string,unknown>){patch({[field]:[...rows(field),value]});}
  function remove(field:string,index:number){patch({[field]:rows(field).filter((_,i)=>i!==index)});}
  const csv=(v:string)=>v.split(',').map(s=>s.trim()).filter(Boolean);
</script>
{#if selected.kind==='trigger'}
<label>Command category<input value={selected.category || 'General'} maxlength="80" onchange={e=>patch({category:e.currentTarget.value})}/></label>
<details><summary>Permissions & checks</summary><div class="settings-fields">
<label>Required permission<select value={selected.checks?.permission || ''} onchange={e=>patch({checks:{...selected.checks,permission:e.currentTarget.value || null}})}><option value="">None</option>{#each ['manage_guild','manage_messages','manage_roles','kick_members','ban_members','moderate_members','administrator'] as p}<option value={p}>{p.replaceAll('_',' ')}</option>{/each}</select></label>
<label class="checkbox-label"><input type="checkbox" checked={selected.checks?.server_only} onchange={e=>patch({checks:{...selected.checks,server_only:e.currentTarget.checked}})}/> Server only</label>
<label class="checkbox-label"><input type="checkbox" checked={selected.checks?.age_restricted} onchange={e=>patch({checks:{...selected.checks,age_restricted:e.currentTarget.checked}})}/> Age-restricted channel only</label>
<label>Allowed channel IDs<input value={selected.checks?.channels?.join(', ') || ''} onchange={e=>patch({checks:{...selected.checks,channels:csv(e.currentTarget.value)}})}/></label>
<label>Required role IDs (any)<input value={selected.checks?.roles?.join(', ') || ''} onchange={e=>patch({checks:{...selected.checks,roles:csv(e.currentTarget.value)}})}/></label>
</div></details>
<details><summary>Typed command arguments</summary>
{#each selected.options || [] as o,i}<div class="feature-card">
<label>Argument name<input value={o.name} onchange={e=>update('options',i,{name:e.currentTarget.value})}/></label>
<label>Argument description<input value={o.description} onchange={e=>update('options',i,{description:e.currentTarget.value})}/></label>
<label>Argument type<select value={o.type} onchange={e=>update('options',i,{type:e.currentTarget.value,default:e.currentTarget.value==='bool'?false:e.currentTarget.value==='str'?'':0,choices:[],autocomplete:[]})}><option value="str">Text</option><option value="int">Integer</option><option value="float">Number</option><option value="bool">Boolean</option></select></label>
<label class="checkbox-label"><input type="checkbox" checked={o.required} onchange={e=>update('options',i,{required:e.currentTarget.checked})}/> Required argument</label>
{#if !o.required}<label>Argument default<input value={String(o.default ?? '')} onchange={e=>update('options',i,{default:o.type==='bool'?e.currentTarget.value==='true':o.type==='str'?e.currentTarget.value:Number(e.currentTarget.value)})}/></label>{/if}
{#if o.type==='str'}<label>Fixed choices (comma separated)<input value={o.choices?.join(', ') || ''} onchange={e=>update('options',i,{choices:csv(e.currentTarget.value),autocomplete:[]})}/></label><label>Autocomplete suggestions<input value={o.autocomplete?.join(', ') || ''} onchange={e=>update('options',i,{autocomplete:csv(e.currentTarget.value),choices:[]})}/></label>{/if}
<button class="text-button danger" onclick={()=>remove('options',i)}>Remove argument</button></div>{/each}
<button class="text-button" onclick={()=>add('options',{name:`argument_${(selected.options || []).length+1}`,type:'str',description:'Command argument',required:true,default:'',choices:[],autocomplete:[]})}>Add command argument</button><p class="micro">Use {'{{options.argument_name}}'} in responses. Quote prefix text containing spaces.</p></details>
{:else if selected.kind==='embed'}
<label>Embed footer<input value={selected.footer || ''} onchange={e=>patch({footer:e.currentTarget.value})}/></label><label>Thumbnail URL<input type="url" value={selected.thumbnail_url || ''} onchange={e=>patch({thumbnail_url:e.currentTarget.value || null})}/></label><label>Title link URL<input type="url" value={selected.url || ''} onchange={e=>patch({url:e.currentTarget.value || null})}/></label>
{#each selected.fields || [] as f,i}<div class="feature-card"><label>Field name<input value={f.name} onchange={e=>update('fields',i,{name:e.currentTarget.value})}/></label><label>Field value<textarea rows="2" value={f.value} onchange={e=>update('fields',i,{value:e.currentTarget.value})}></textarea></label><label class="checkbox-label"><input type="checkbox" checked={f.inline} onchange={e=>update('fields',i,{inline:e.currentTarget.checked})}/> Inline field</label><button class="text-button danger" onclick={()=>remove('fields',i)}>Remove field</button></div>{/each}<button class="text-button" onclick={()=>add('fields',{name:'Field',value:'Value',inline:false})}>Add embed field</button>
{:else if selected.kind==='message'}
<label>Interactive message<textarea rows="3" value={selected.content} onchange={e=>patch({content:e.currentTarget.value})}></textarea></label><label class="checkbox-label"><input type="checkbox" checked={selected.owner_only ?? true} onchange={e=>patch({owner_only:e.currentTarget.checked})}/> Only the invoker can interact</label><label>Interaction timeout (seconds)<input type="number" min="1" max="900" value={selected.timeout || 180} onchange={e=>patch({timeout:+e.currentTarget.value})}/></label>
{#each selected.buttons || [] as b,i}<div class="feature-card"><label>Button label<input value={b.label} onchange={e=>update('buttons',i,{label:e.currentTarget.value})}/></label><label>Button reply<textarea rows="2" value={b.reply} onchange={e=>update('buttons',i,{reply:e.currentTarget.value})}></textarea></label><label>Button link (optional)<input type="url" value={b.url || ''} onchange={e=>update('buttons',i,{url:e.currentTarget.value || null})}/></label><button class="text-button danger" onclick={()=>remove('buttons',i)}>Remove button</button></div>{/each}<button class="text-button" onclick={()=>add('buttons',{label:'Click me',reply:'Hello!',url:null,style:'secondary'})}>Add reply button</button>
{#each selected.selects || [] as d,i}<div class="feature-card"><label>Dropdown placeholder<input value={d.placeholder} onchange={e=>update('selects',i,{placeholder:e.currentTarget.value})}/></label><label>Dropdown options<input value={d.options?.join(', ') || ''} onchange={e=>update('selects',i,{options:csv(e.currentTarget.value)})}/></label><label>Dropdown reply<textarea rows="2" value={d.reply} onchange={e=>update('selects',i,{reply:e.currentTarget.value})}></textarea></label><button class="text-button danger" onclick={()=>remove('selects',i)}>Remove dropdown</button></div>{/each}<button class="text-button" onclick={()=>add('selects',{placeholder:'Choose an option',options:['One','Two'],reply:'You chose {{input.value}}'})}>Add dropdown</button>
{#each selected.attachments || [] as a,i}<div class="feature-card"><label>Attachment filename<input value={a.filename} onchange={e=>update('attachments',i,{filename:e.currentTarget.value})}/></label><label>Text file contents<textarea rows="3" value={a.content} onchange={e=>update('attachments',i,{content:e.currentTarget.value})}></textarea></label><button class="text-button danger" onclick={()=>remove('attachments',i)}>Remove attachment</button></div>{/each}<button class="text-button" onclick={()=>add('attachments',{filename:'report.txt',content:'Report contents'})}>Add text attachment</button>
{:else if selected.kind==='form'}
<label>Form title<input value={selected.title} maxlength="45" onchange={e=>patch({title:e.currentTarget.value})}/></label>
{#each selected.inputs || [] as f,i}<div class="feature-card"><label>Input name<input value={f.name} onchange={e=>update('inputs',i,{name:e.currentTarget.value})}/></label><label>Input label<input value={f.label} onchange={e=>update('inputs',i,{label:e.currentTarget.value})}/></label><label>Maximum input length<input type="number" min="1" max="4000" value={f.max_length} onchange={e=>update('inputs',i,{max_length:+e.currentTarget.value})}/></label><label class="checkbox-label"><input type="checkbox" checked={f.required} onchange={e=>update('inputs',i,{required:e.currentTarget.checked})}/> Required field</label><label class="checkbox-label"><input type="checkbox" checked={f.paragraph} onchange={e=>update('inputs',i,{paragraph:e.currentTarget.checked})}/> Paragraph input</label><button class="text-button danger" onclick={()=>remove('inputs',i)}>Remove input</button></div>{/each}<button class="text-button" onclick={()=>add('inputs',{name:`field_${(selected.inputs || []).length+1}`,label:'Your answer',required:true,max_length:1000,paragraph:false})}>Add form input</button>
<label>Form submission reply<textarea rows="3" value={selected.response} onchange={e=>patch({response:e.currentTarget.value})}></textarea></label><p class="micro">Use {'{{input.field_name}}'} in the submission reply. Forms are the first response of a slash-only command and end a flow.</p>
{:else if selected.kind==='action'}
<label>Action type<select value={selected.operation || 'store_get'} onchange={e=>patch({operation:e.currentTarget.value,response:(e.currentTarget.value.startsWith('store_') || e.currentTarget.value.startsWith('setting_'))?'Value: {{store.value}}':'Done.'})}><option value="store_get">Read server data</option><option value="store_set">Write server data</option><option value="store_increment">Increment server counter</option><option value="setting_get">Read a versioned server setting</option><option value="setting_set">Update a versioned server setting</option><option value="moderation">Moderation confirmation</option><option value="schedule">Schedule a message</option><option value="cancel_job">Cancel your scheduled job</option></select></label>
{#if selected.operation?.startsWith('store_') || selected.operation?.startsWith('setting_') || !selected.operation}<label>Storage key<input value={selected.key || 'visits'} onchange={e=>patch({key:e.currentTarget.value})}/></label>{#if selected.operation!=='store_get' && selected.operation!=='setting_get'}<label>Value or increment<input value={selected.value ?? '1'} onchange={e=>patch({value:e.currentTarget.value})}/></label>{/if}<label>Action reply<textarea rows="2" value={selected.response || 'Value: {{store.value}}'} onchange={e=>patch({response:e.currentTarget.value})}></textarea></label>
{:else if selected.operation==='moderation'}<label>Moderation action<select value={selected.moderation_action || 'kick'} onchange={e=>patch({moderation_action:e.currentTarget.value})}><option value="kick">Kick</option><option value="ban">Ban</option><option value="timeout">Timeout</option></select></label><label>Target member ID or argument<input value={selected.target || '{{user.id}}'} onchange={e=>patch({target:e.currentTarget.value})}/></label><label>Audit reason<input value={selected.reason || 'Moderator request'} onchange={e=>patch({reason:e.currentTarget.value})}/></label>{#if selected.moderation_action==='timeout'}<label>Timeout minutes<input type="number" min="1" max="40320" value={selected.minutes || 10} onchange={e=>patch({minutes:+e.currentTarget.value})}/></label>{/if}<p class="micro">A confirmation prompt ends this flow. Live execution rechecks bot/caller permissions and role hierarchy. Preview never moderates a real member.</p>
{:else if selected.operation==='schedule'}<label>Scheduled message<textarea rows="3" value={selected.value || ''} onchange={e=>patch({value:e.currentTarget.value})}></textarea></label><label>Delay seconds<input type="number" min="0" value={selected.delay ?? 60} onchange={e=>patch({delay:+e.currentTarget.value})}/></label><label>Retries<input type="number" min="0" max="10" value={selected.retries ?? 3} onchange={e=>patch({retries:+e.currentTarget.value})}/></label>
{:else}<label>Job ID or argument<input value={selected.value || ''} onchange={e=>patch({value:e.currentTarget.value})}/></label>{/if}
{/if}
